"""SQLite tables of the supply chain ontology (Supplier → Part → PO → Shipment → Warehouse → Plant → Order)."""
from backend.core.db import TableSpec
from backend.features.supply_chain_intelligence.schemas.ontology import (
    AlternativeSupplierContract, BillOfMaterials, Carrier, CustomerOrder, DemandForecast, DisruptionEvent,
    ExcessInventoryItem, InventoryItem, MitigationRecommendation, Part, Plant, ProductionSchedule, PurchaseOrder,
    Shipment, Supplier, Warehouse,
)

F = "supply_chain_intelligence"
SC_TABLES = {
    "plants": TableSpec("sc_plants", "Plants and their daily production targets.", Plant, key=lambda m: m.plant_id,
                        columns={"country": lambda m: m.country}, feature=F),
    "suppliers": TableSpec("sc_suppliers", "Suppliers with tier, category and composite risk.", Supplier, key=lambda m: m.supplier_id,
                           columns={"country": lambda m: m.country, "category": lambda m: m.category, "risk_level": lambda m: m.composite_risk_level},
                           indexes=("risk_level",), feature=F),
    "parts": TableSpec("sc_parts", "Parts with primary / alternate supplier and cost.", Part, key=lambda m: m.part_id,
                       columns={"primary_supplier_id": lambda m: m.primary_supplier_id, "unit_cost_usd": lambda m: m.unit_cost_usd},
                       indexes=("primary_supplier_id",), feature=F),
    "boms": TableSpec("sc_bill_of_materials", "Bill of materials: parts per finished assembly.", BillOfMaterials,
                      key=lambda m: f"{m.finished_assembly_id}:{m.part_id}", kind="list",
                      columns={"finished_assembly_id": lambda m: m.finished_assembly_id, "part_id": lambda m: m.part_id},
                      indexes=("finished_assembly_id", "part_id"), feature=F),
    "inventory": TableSpec("sc_inventory_balances", "Stock per part, warehouse and plant with stock-out risk.", InventoryItem, key=lambda m: m.part_id,
                           columns={"part_id": lambda m: m.part_id, "plant_id": lambda m: m.plant_id, "warehouse_id": lambda m: m.warehouse_id,
                                    "stockout_risk_score": lambda m: m.stockout_risk_score},
                           indexes=("plant_id",), feature=F),
    "purchase_orders": TableSpec("sc_purchase_orders", "Purchase orders and their status.", PurchaseOrder, key=lambda m: m.po_id,
                                 columns={"supplier_id": lambda m: m.supplier_id, "part_id": lambda m: m.part_id, "po_status": lambda m: m.po_status},
                                 indexes=("supplier_id", "po_status"), feature=F),
    "shipments": TableSpec("sc_shipments", "Inbound shipments by carrier and status.", Shipment, key=lambda m: m.shipment_id,
                           columns={"po_id": lambda m: m.po_id, "status": lambda m: m.status}, indexes=("status",), feature=F),
    "customer_orders": TableSpec("sc_customer_orders", "Customer orders, revenue and status.", CustomerOrder, key=lambda m: m.order_id,
                                 columns={"plant_id": lambda m: m.plant_id, "order_status": lambda m: m.order_status, "revenue_usd": lambda m: m.revenue_usd},
                                 indexes=("order_status",), feature=F),
    "disruptions": TableSpec("sc_disruptions", "Supply disruption events.", DisruptionEvent, key=lambda m: m.disruption_id,
                             columns={"severity": lambda m: m.severity, "resolved_flag": lambda m: int(bool(m.resolved))}, indexes=("severity",), feature=F),
    "mitigations": TableSpec("sc_mitigations", "Mitigation recommendations and their approval.", MitigationRecommendation, key=lambda m: m.recommendation_id,
                             columns={"disruption_id": lambda m: m.disruption_id, "status": lambda m: m.status, "approved_by": lambda m: m.approved_by},
                             indexes=("status",), feature=F),
    "carriers": TableSpec("sc_carriers", "Carriers and on-time performance.", Carrier, key=lambda m: m.carrier_id, feature=F),
    "warehouses": TableSpec("sc_warehouses", "Warehouses, capacity and utilisation.", Warehouse, key=lambda m: m.warehouse_id,
                            columns={"associated_plant_id": lambda m: m.associated_plant_id}, feature=F),
    "production_schedules": TableSpec("sc_production_schedules", "Production schedules per line and assembly.", ProductionSchedule, key=lambda m: m.schedule_id,
                                      columns={"plant_id": lambda m: m.plant_id, "line_id": lambda m: m.line_id}, feature=F),
    "demand_forecasts": TableSpec("sc_demand_forecasts", "Demand forecasts per assembly.", DemandForecast, key=lambda m: m.forecast_id,
                                  columns={"assembly_id": lambda m: m.assembly_id}, feature=F),
    "alternative_contracts": TableSpec("sc_alternative_contracts", "Pre-negotiated alternative supplier contracts.", AlternativeSupplierContract,
                                       key=lambda m: m.contract_id, columns={"part_id": lambda m: m.part_id}, feature=F),
    "excess_inventory": TableSpec("sc_excess_inventory", "Excess / obsolescence-risk inventory.", ExcessInventoryItem, key=lambda m: m.part_id, feature=F),
}
